"""Wide-separation terms generated by mathwap (pk/Pk_WS.py, pk/Pk_WSGR.py, bk/WS_.py, bk/WA2.py's l2, bk_mt's WS classes).

pk: each class's multipoles against its own mu(), with and without FoG, and the two-tracer swap symmetry RR2.l0 used
to break. bk: WA2.l2 (MathWAP's export was wrong) against the exact projection of the angle-dependent form, that
projection against numerical integration, bk_mt with one tracer against bk, and FoG -> undamped as sigma -> 0.
"""

import numpy as np
import pytest
from scipy.special import eval_legendre

from cosmo_wap import bk, bk_mt, pk
from cosmo_wap.bk import WS_
from cosmo_wap.bk.combined import bk_func

K = np.array([0.003, 0.02, 0.1])
TRI = dict(k1=np.array([0.02, 0.05, 0.08]), k2=np.array([0.015, 0.04, 0.05]), theta=np.array([2.0, 1.2, 2.6]))


@pytest.mark.parametrize("name", ["WA1", "RR1", "WA2", "WARR", "RR2", "WAGR", "RRGR"])
@pytest.mark.parametrize("sigma", [None, 0.01, 4.0])
def test_pk_multipoles_match_mu(cosmo_funcs, name, sigma):
    """(2l+1)/2 int P(k, mu) L_l dmu by Gauss-Legendre, damped as the closed forms: exp(-(k mu sigma)^2/2)"""
    cls = getattr(pk, name)
    scale = np.max(np.abs([cls.mu(m, cosmo_funcs, K, 1.0, 0.3) for m in np.linspace(-1, 1, 9)]), axis=0)
    x, w = np.polynomial.legendre.leggauss(40)
    P = np.array([cls.mu(xi, cosmo_funcs, K, 1.0, 0.3) for xi in x])
    if sigma is not None:
        P = P * np.exp(-((K[None, :] * x[:, None] * sigma) ** 2) / 2)
    for l in range(7):
        got = getattr(cls, f"l{l}")(cosmo_funcs, K, 1.0, 0.3, sigma)
        want = (2 * l + 1) / 2 * np.sum(w[:, None] * P * eval_legendre(l, x)[:, None], axis=0)
        np.testing.assert_allclose(got, want, rtol=0, atol=1e-10 * np.max(scale))


class _Swapped:
    """cosmo_funcs with its two tracers swapped, as far as unpack_pk(WS, RR) goes"""

    def __init__(self, cosmo_funcs):
        self.cf = cosmo_funcs

    def unpack_pk(self, k1, zz, WS=False, RR=False):
        p = self.cf.unpack_pk(k1, zz, WS=WS, RR=RR)
        for i, j in ((3, 4), (10, 11), (14, 15)):  # b1/xb1, bd1/xbd1, bdd1/xbdd1
            p[i], p[j] = p[j], p[i]
        return p


@pytest.mark.parametrize("sigma", [None, 4.0])
def test_pk_rr2_two_tracer_swap(forecast_mt, sigma):
    """P_AB(k; t) = P_BA(k; 1-t) for the even multipoles - the old RR2.l0 broke it by ~40%"""
    cf = forecast_mt.cosmo_funcs
    for l in (0, 2, 4):
        a = getattr(pk.RR2, f"l{l}")(cf, K, 1.0, 0.2, sigma)
        b = getattr(pk.RR2, f"l{l}")(_Swapped(cf), K, 1.0, 0.8, sigma)
        np.testing.assert_allclose(a, b, rtol=1e-10)


def test_bk_wa2_l2_matches_projection(cosmo_funcs):
    for l in (0, 2):
        got = getattr(bk.WA2, f"l{l}")(cosmo_funcs, **TRI, zz=1.0, r=0.3, s=0.2)
        want = WS_._ylm("WA2", l, 0, cosmo_funcs, **TRI, zz=1.0, r=0.3, s=0.2)
        np.testing.assert_allclose(got, want, rtol=1e-9)


@pytest.mark.parametrize("block,l,m", [("RR1", 1, 1), ("WAGR", 2, 0), ("WA2", 4, 2)])
def test_bk_exact_projection_matches_numerical(cosmo_funcs, block, l, m):
    func = WS_._BLOCKS[block][2]
    exact = WS_._ylm(block, l, m, cosmo_funcs, **TRI, zz=1.0, r=0.3, s=0.2)
    num = WS_._ylm_num(func, l, m, cosmo_funcs, TRI["k1"], TRI["k2"], None, TRI["theta"], 1.0, 0.3, 0.2, n=32)
    np.testing.assert_allclose(exact, np.squeeze(num), rtol=1e-9)


@pytest.mark.parametrize("term", ["WS", "WSGR"])
def test_bk_mt_one_tracer_matches_bk(cosmo_funcs, term):
    """bk_mt's classes come from WS_ only; bk's use MathWAP's analytic multipoles where they exist"""
    args = (cosmo_funcs, TRI["k1"], TRI["k2"], None, TRI["theta"], 1.0, 0.3, 0.2)
    for l in range(4):
        np.testing.assert_allclose(
            getattr(getattr(bk_mt, term), f"l{l}")(*args),
            getattr(getattr(bk, term), f"l{l}")(*args),
            rtol=1e-9,
            atol=1e-20,
        )


def test_bk_fog_tends_to_undamped(cosmo_funcs):
    plain = bk_func("WSGR", 2, cosmo_funcs, **TRI, zz=1.0)
    damped = bk_func("WSGR", 2, cosmo_funcs, **TRI, zz=1.0, sigma=1e-3)
    np.testing.assert_allclose(damped, plain, rtol=1e-6)
